"""Generate the self-contained drop-in/lab file sent to the judge."""
from pathlib import Path

HERE = Path(__file__).resolve().parent
out = HERE.parent / "streaming_gemv_lab.py"
out.write_text(
    '"""Streaming BF16 projections: generated by dev/streaming/build.py."""\n'
    + "SP_CUDA = " + repr((HERE / "kernel.cu").read_text()) + "\n\n"
    + (HERE / "runtime.py.inc").read_text() + "\n\n"
    + (HERE / "lab.py.inc").read_text()
)
print(out)
